const section = (t) => (t < 18 ? '钢琴前奏' : t < 67.5 ? '主歌一' : t < 103 ? '副歌一' : t < 123 ? '间奏' : t < 172.6 ? '主歌二' : t < 208 ? '副歌二' : t < 246.7 ? '尾段副歌' : '钢琴尾奏');

